files.terraform/main.tf:
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.68"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.9"
    }
  }
  required_version = ">= 1.5"
}

provider "aws" {
  region = var.aws_region
}

# VPC
resource "aws_vpc" "main" {
  cidr_block = var.vpc_cidr
  tags       = { Name = "vpc-main" }
}

# Internet Gateway
resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.main.id
  tags   = { Name = "igw" }
}

# Public Subnet (for ALB and NAT)
resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.public_subnet_cidr
  availability_zone       = var.public_subnet_az

  tags                    = { Name = "subnet-public" }

  map_public_ip_on_launch = false
}

# Private Subnets
resource "aws_subnet" "private_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.private_subnet_a_cidr
  availability_zone       = var.private_subnet_a_az
  map_public_ip_on_launch = false
  tags                    = { Name = "subnet-a" }
}

resource "aws_subnet" "private_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.private_subnet_b_cidr
  availability_zone       = var.private_subnet_b_az
  map_public_ip_on_launch = false
  tags                    = { Name = "subnet-b" }
}

# Route Table for Public Subnet
resource "aws_route_table" "public_rt" {
  vpc_id = aws_vpc.main.id
  tags   = { Name = "rt-public" }
}

resource "aws_route" "public_igw" {
  route_table_id         = aws_route_table.public_rt.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.igw.id
}

resource "aws_route_table_association" "public_assoc" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public_rt.id
}

# NAT Gateway
resource "aws_eip" "nat_eip" {
  domain = "vpc"
}

resource "aws_nat_gateway" "natgw" {
  allocation_id = aws_eip.nat_eip.id
  subnet_id     = aws_subnet.public.id
  tags          = { Name = "natgw" }
}

# Route Table for Private Subnets
resource "aws_route_table" "private_rt" {
  vpc_id = aws_vpc.main.id
  tags   = { Name = "rt-private" }
}

resource "aws_route" "private_nat" {
  route_table_id         = aws_route_table.private_rt.id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.natgw.id
}

resource "aws_route_table_association" "private_a_assoc" {
  subnet_id      = aws_subnet.private_a.id
  route_table_id = aws_route_table.private_rt.id
}

resource "aws_route_table_association" "private_b_assoc" {
  subnet_id      = aws_subnet.private_b.id
  route_table_id = aws_route_table.private_rt.id
}

# Security Groups
resource "aws_security_group" "alb_sg" {
  name        = "sg-alb"
  description = "Allow inbound HTTPS"
  vpc_id      = aws_vpc.main.id
  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }
}

resource "aws_security_group" "ecs_sg" {
  name        = "sg-ecs"
  description = "ECS task SG"
  vpc_id      = aws_vpc.main.id
  ingress {
    from_port       = 0
    to_port         = 0
    protocol        = "-1"
    security_groups = [aws_security_group.alb_sg.id]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }
}

resource "aws_security_group" "rds_sg" {
  name        = "sg-rds"
  description = "RDS SG"
  vpc_id      = aws_vpc.main.id
  ingress {
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.ecs_sg.id]
  }
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [var.vpc_cidr]
  }
}

# ALB
resource "aws_lb" "alb" {
  name                       = "api-alb"
  internal                   = false
  load_balancer_type         = "application"
  subnets                    = [aws_subnet.public.id]
  security_groups            = [aws_security_group.alb_sg.id]
  enable_deletion_protection = false
  tags                       = { Name = "alb" }
  drop_invalid_header_fields = true
}

resource "aws_lb_target_group" "tg" {
  name        = "api-tg"
  port        = 80
  protocol    = "HTTP"
  vpc_id      = aws_vpc.main.id
  target_type = "ip"
  health_check {
    path                = "/health"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 2
    matcher             = "200-299"
  }
}

resource "aws_lb_listener" "https_listener" {
  load_balancer_arn = aws_lb.alb.arn
  port              = "443"
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = var.acm_certificate_arn
  default_action {
    type = "forward"
    forward {
      target_group {
        arn = aws_lb_target_group.tg.arn
      }
    }
  }
}

# ECS Cluster
resource "aws_ecs_cluster" "cluster" {
  name = "ecs-cluster"
}

# IAM Role for ECS Task Execution
resource "aws_iam_role" "ecs_task_execution" {
  name = "ecsTaskExecutionRole"
  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [{
      Effect    = "Allow",
      Principal = { Service = "ecs-tasks.amazonaws.com" },
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_policy_attachment" "ecs_execution_attach" {
  name       = "ecs-exec-policy"
  roles      = [aws_iam_role.ecs_task_execution.name]
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonECSTaskExecutionRolePolicy"
}

# ECS Task Definition
resource "aws_ecs_task_definition" "api_task" {
  family                   = "api-service"
  network_mode             = "awsvpc"
  requires_compatibilities = ["FARGATE"]
  cpu                      = "256"
  memory                   = "512"
  execution_role_arn       = aws_iam_role.ecs_task_execution.arn
  container_definitions = jsonencode([
    {
      name         = "api"
      image        = var.ecr_image
      portMappings = [{ containerPort = 80, protocol = "tcp" }]
      logConfiguration = {
        logDriver = "awslogs"
        options = {
          "awslogs-group"         = aws_cloudwatch_log_group.api_logs.name
          "awslogs-region"        = var.aws_region
          "awslogs-stream-prefix" = "api"
        }
      }
    }
  ])
}

# ECS Service
resource "aws_ecs_service" "api_service" {
  name            = "api-service"
  cluster         = aws_ecs_cluster.cluster.id
  task_definition = aws_ecs_task_definition.api_task.arn
  desired_count   = 2
  launch_type     = "FARGATE"
  network_configuration {
    subnets          = [aws_subnet.private_a.id, aws_subnet.private_b.id]
    security_groups  = [aws_security_group.ecs_sg.id]
    assign_public_ip = false
  }
  load_balancer {
    target_group_arn = aws_lb_target_group.tg.arn
    container_name   = "api"
    container_port   = 80
  }
  deployment_minimum_healthy_percent = 50
  deployment_maximum_percent         = 200
}

# CloudWatch Log Group
resource "aws_cloudwatch_log_group" "api_logs" {
  name              = "/ecs/api-service"
  retention_in_days = 14
}

# RDS Subnet Group
resource "aws_db_subnet_group" "rds_subnet" {
  name       = "postgres-db-subnet"
  subnet_ids = [aws_subnet.private_a.id, aws_subnet.private_b.id]
  tags       = { Name = "rds-subnet-group" }
}

# RDS Instance
resource "aws_db_instance" "postgres" {
  identifier                          = "postgres-db"
  engine                              = "postgres"
  engine_version                      = "15"
  instance_class                      = var.db_instance_class
  allocated_storage                   = 20
  db_name                             = var.db_name
  username                            = var.db_username
  password                            = data.aws_secretsmanager_secret_version.db_secret.secret_string
  db_subnet_group_name                = aws_db_subnet_group.rds_subnet.name
  vpc_security_group_ids              = [aws_security_group.rds_sg.id]
  backup_retention_period             = var.backup_retention_days
  deletion_protection                 = true
  storage_encrypted                   = true
  iam_database_authentication_enabled = true
  enabled_cloudwatch_logs_exports     = ["postgresql"]
  performance_insights_enabled        = true
  monitoring_interval                 = 60
  monitoring_role_arn                 = aws_iam_role.rds_monitoring.arn
  skip_final_snapshot                 = false
  final_snapshot_identifier           = "postgres-db-final-snapshot"
  tags                                = { Name = "postgres-db" }
}

# IAM Role for RDS Monitoring
resource "aws_iam_role" "rds_monitoring" {
  name = "rds-monitoring-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [{
      Effect    = "Allow",
      Principal = { Service = "monitoring.rds.amazonaws.com" },
      Action    = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "rds_monitoring_attach" {
  role       = aws_iam_role.rds_monitoring.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSEnhancedMonitoringRole"
}

# Secrets Manager Secret (reference only)

data "aws_secretsmanager_secret" "db_secret" {
  name = var.db_secret_name
}

data "aws_secretsmanager_secret_version" "db_secret" {
  secret_id = data.aws_secretsmanager_secret.db_secret.id
}

# ECR Repository Data Source

data "aws_ecr_repository" "api_repo" {
  name = var.ecr_repo_name
}

# Output ALB DNS
output "alb_dns_name" {
  value = aws_lb.alb.dns_name
}

files.terraform/variables.tf:
variable "aws_region" {
  description = "AWS region"
  type        = string
  default     = "eu-central-1"
}

variable "vpc_cidr" {
  description = "CIDR block for VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "public_subnet_cidr" {
  description = "CIDR for public subnet"
  type        = string
  default     = "10.0.1.0/24"
}

variable "public_subnet_az" {
  description = "AZ for public subnet"
  type        = string
  default     = "eu-central-1a"
}

variable "private_subnet_a_cidr" {
  description = "CIDR for private subnet A"
  type        = string
  default     = "10.0.2.0/24"
}

variable "private_subnet_a_az" {
  description = "AZ for private subnet A"
  type        = string
  default     = "eu-central-1a"
}

variable "private_subnet_b_cidr" {
  description = "CIDR for private subnet B"
  type        = string
  default     = "10.0.3.0/24"
}

variable "private_subnet_b_az" {
  description = "AZ for private subnet B"
  type        = string
  default     = "eu-central-1b"
}

variable "acm_certificate_arn" {
  description = "ARN of existing ACM certificate for ALB"
  type        = string
}

variable "ecr_repo_name" {
  description = "Name of ECR repository holding the API image"
  type        = string
  default     = "api-repo"
}

variable "ecr_image" {
  description = "Full image URI (including tag) for API container"
  type        = string
}

variable "db_instance_class" {
  description = "RDS instance class"
  type        = string
  default     = "db.t3.micro"
}

variable "db_name" {
  description = "Database name"
  type        = string
  default     = "appdb"
}

variable "db_username" {
  description = "Database master username"
  type        = string
  default     = "admin"
}

variable "db_secret_name" {
  description = "Name of Secrets Manager secret containing DB password"
  type        = string
}

variable "backup_retention_days" {
  description = "Number of days to retain automated backups"
  type        = number
  default     = 7
}

files.terraform/security_support.tf:
resource "aws_cloudwatch_log_group" "infraarch_vpc_flow" {
  name_prefix = "/infraarch/vpc-flow-"
  retention_in_days = 365
  kms_key_id = "${aws_kms_key.infraarch_security.arn}"
}

resource "aws_flow_log" "infraarch_main" {
  vpc_id = "${aws_vpc.main.id}"
  traffic_type = "ALL"
  log_destination_type = "cloud-watch-logs"
  log_destination = "${aws_cloudwatch_log_group.infraarch_vpc_flow.arn}"
  iam_role_arn = "${aws_iam_role.infraarch_vpc_flow.arn}"
  depends_on = [aws_iam_role_policy.infraarch_vpc_flow]
}

resource "aws_iam_role" "infraarch_vpc_flow" {
  name_prefix = "infraarch-flow-"
  assume_role_policy = "{\"Version\": \"2012-10-17\", \"Statement\": [{\"Effect\": \"Allow\", \"Principal\": {\"Service\": \"vpc-flow-logs.amazonaws.com\"}, \"Action\": \"sts:AssumeRole\", \"Condition\": {\"StringEquals\": {\"aws:SourceAccount\": \"${data.aws_caller_identity.infraarch_security.account_id}\"}}}]}"
}

resource "aws_iam_role_policy" "infraarch_vpc_flow" {
  name_prefix = "infraarch-flow-"
  role = "${aws_iam_role.infraarch_vpc_flow.id}"
  policy = "{\"Version\": \"2012-10-17\", \"Statement\": [{\"Effect\": \"Allow\", \"Action\": [\"logs:CreateLogStream\", \"logs:PutLogEvents\", \"logs:DescribeLogStreams\"], \"Resource\": \"${aws_cloudwatch_log_group.infraarch_vpc_flow.arn}:*\"}, {\"Effect\": \"Allow\", \"Action\": [\"logs:DescribeLogGroups\"], \"Resource\": \"*\"}]}"
}

resource "aws_kms_alias" "infraarch_security" {
  name_prefix = "alias/infraarch-security-"
  target_key_id = "${aws_kms_key.infraarch_security.key_id}"
}

resource "aws_kms_key" "infraarch_security" {
  description = "Infrastructure security encryption"
  enable_key_rotation = true
  deletion_window_in_days = 30
  policy = "{\"Version\": \"2012-10-17\", \"Statement\": [{\"Sid\": \"AccountAdministration\", \"Effect\": \"Allow\", \"Principal\": {\"AWS\": \"arn:${data.aws_partition.infraarch_security.partition}:iam::${data.aws_caller_identity.infraarch_security.account_id}:root\"}, \"Action\": \"kms:*\", \"Resource\": \"*\"}, {\"Sid\": \"ScopedLogEncryption\", \"Effect\": \"Allow\", \"Principal\": {\"Service\": \"logs.${data.aws_region.infraarch_security.name}.${data.aws_partition.infraarch_security.dns_suffix}\"}, \"Action\": [\"kms:Encrypt\", \"kms:Decrypt\", \"kms:ReEncrypt*\", \"kms:GenerateDataKey*\", \"kms:DescribeKey\"], \"Resource\": \"*\", \"Condition\": {\"ArnLike\": {\"kms:EncryptionContext:aws:logs:arn\": \"arn:${data.aws_partition.infraarch_security.partition}:logs:${data.aws_region.infraarch_security.name}:${data.aws_caller_identity.infraarch_security.account_id}:log-group:/infraarch/vpc-flow-*\"}}}]}"
}

data "aws_caller_identity" "infraarch_security" {
}

data "aws_partition" "infraarch_security" {
}

data "aws_region" "infraarch_security" {
}

