  name            = "api-service"
  cluster         = aws_ecs_cluster.cluster.id
  task_definition = aws_ecs_task_definition.api_task.arn
  desired_count   = 2
  launch_type     = "FARGATE"
  network_configuration {
    subnets         = [aws_subnet.private_a.id, aws_subnet.private_b.id]
    security_groups = [aws_security_group.ecs_sg.id]
    assign_public_ip = false
  }
  load_balancer {
    target_group_arn = aws_lb_target_group.tg.arn
    container_name   = "api"
    container_port   = 80
  }
  deployment_minimum_healthy_percent = 50
  deployment_maximum_percent         = 200
}

# CloudWatch Log Group
resource "aws_cloudwatch_log_group" "api_logs" {
  name = "/ecs/api-service"
  retention_in_days = 14
}

# RDS Subnet Group
resource "aws_db_subnet_group" "rds_subnet" {
  name       = "postgres-db-subnet"
  subnet_ids = [aws_subnet.private_a.id, aws_subnet.private_b.id]
  tags = { Name = "rds-subnet-group" }
}

# RDS Instance
resource "aws_db_instance" "postgres" {
  identifier               = "postgres-db"
  engine                   = "postgres"
  engine_version           = "15"
  instance_class           = var.db_instance_class
  allocated_storage        = 20
  name                     = var.db_name
  username                 = var.db_username
  password                 = data.aws_secretsmanager_secret_version.db_secret.secret_string
  db_subnet_group_name     = aws_db_subnet_group.rds_subnet.name
  vpc_security_group_ids  = [aws_security_group.rds_sg.id]
  backup_retention_period = var.backup_retention_days
  deletion_protection      = true
  storage_encrypted        = true
  iam_database_authentication_enabled = true
  enabled_cloudwatch_logs_exports = ["postgresql"]
  performance_insights_enabled = true
  monitoring_interval = 60
  monitoring_role_arn = aws_iam_role.rds_monitoring.arn
  skip_final_snapshot   = false
  final_snapshot_identifier = "postgres-db-final-snapshot"
  tags = { Name = "postgres-db" }
}

# IAM Role for RDS Monitoring
resource "aws_iam_role" "rds_monitoring" {
  name = "rds-monitoring-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17",
    Statement = [{
      Effect = "Allow",
      Principal = { Service = "monitoring.rds.amazonaws.com" },
      Action = "sts:AssumeRole"
    }]
  })
}

resource "aws_iam_role_policy_attachment" "rds_monitoring_attach" {
  role       = aws_iam_role.rds_monitoring.name
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSEnhancedMonitoringRole"
}

# Secrets Manager Secret (reference only)

data "aws_secretsmanager_secret" "db_secret" {
  name = var.db_secret_name
}

data "aws_secretsmanager_secret_version" "db_secret" {
  secret_id = data.aws_secretsmanager_secret.db_secret.id
}

# ECR Repository Data Source

data "aws_ecr_repository" "api_repo" {
  name = var.ecr_repo_name
}

# Output ALB DNS
output "alb_dns_name" {
  value = aws_lb.alb.dns_name
}

